    "# =====================================================================================================",
    "# Check 45: check_45_c3a_b4_bottleneck",
    "# =====================================================================================================",
    "if FIRST <= 45 <= LAST:",
    "    print(\"CHECK 45  (check_45_c3a_b4_bottleneck)\")",
    "    ALL_T = frappe.utils.now_datetime()",
    "    passed = []",
    "    failed = []",
    "    try:",
    "        # PEPL OS v0.45.0 - Check 45: C3a-B4 Bottleneck report - how long work waits in front of each machine group between",
    "        # Job Order operations (this operation's start - the previous operation's finish, from the Job Card time logs),",
    "        # overlaps, work waiting now, red above the Wait Warning Hours.",
    "        # Runs on 0.45.0 or later. System Console, Type = Python. Leave \"Commit\" UNTICKED: everything below is undone at the",
    "        # end. Then open the report in the browser: see the steps in the chat.",
    "        VERSION = \"0.45.0\"",
    "        PARAMS = \"PEPL System Parameters\"",
    "        REPORT = \"PEPL Bottleneck\"",
    "        WARNING = \"custom_bottleneck_wait_warning_hours\"",
    "        passed = []",
    "        failed = []",
    "",
    "",
    "        def check(ok, label):",
    "            if ok:",
    "                passed.append(label)",
    "                print(\"PASS  \" + label)",
    "            else:",
    "                failed.append(label)",
    "                print(\"FAIL  \" + label)",
    "",
    "",
    "        def refused(label, action, words):",
    "            try:",
    "                action()",
    "                check(False, label + \" (it was accepted)\")",
    "            except Exception as e:",
    "                text = frappe.utils.strip_html(str(e))",
    "                check(words.lower() in text.lower(), label + \" -> \" + text[:200])",
    "",
    "",
    "        def version_parts(value):",
    "            return [int(part) for part in str(value or \"0\").split(\".\")[:3]]",
    "",
    "",
    "        def run_report(filters):",
    "            return frappe.call(\"frappe.desk.query_report.run\", report_name=REPORT, filters=filters)",
    "",
    "",
    "        RUN = frappe.utils.now().replace(\"-\", \"\").replace(\":\", \"\").replace(\" \", \"\").replace(\".\", \"\")[8:14]",
    "        print(\"INFO  run \" + RUN + \" (all test names end with it)\")",
    "        today = frappe.utils.today()",
    "        DAY = frappe.utils.add_days(today, -2)",
    "        company = frappe.db.get_single_value(\"Global Defaults\", \"default_company\") or frappe.get_all(\"Company\", pluck=\"name\", limit=1)[0]",
    "",
    "",
    "        def wh(store):",
    "            return frappe.db.get_value(\"Warehouse\", {\"company\": company, \"warehouse_name\": store, \"is_group\": 0}, \"name\")",
    "",
    "",
    "        def at(clock):",
    "            return frappe.utils.get_datetime(DAY + \" \" + clock + \":00\")",
    "",
    "",
    "        # ---------------- 1. installed ----------------",
    "        apps = {a.app_name: a.app_version for a in frappe.get_all(\"Installed Application\", fields=[\"app_name\", \"app_version\"])}",
    "        check(version_parts(apps.get(\"pepl_os\")) >= version_parts(VERSION), \"1. pepl_os is \" + VERSION + \" or later (site has \" + str(apps.get(\"pepl_os\")) + \")\")",
    "        check(frappe.db.get_value(\"Report\", REPORT, \"report_type\") == \"Script Report\" and bool(frappe.get_all(\"Workspace Link\", filters={\"parent\": \"Production Command Centre\", \"link_to\": REPORT})),",
    "              \"1. report '\" + REPORT + \"' exists and is listed on the Production Command Centre\")",
    "        check(bool(frappe.get_meta(PARAMS).get_field(WARNING)), \"1. System Parameters > Production > Bottleneck: Wait Warning Hours (this site: \" + str(frappe.db.get_single_value(PARAMS, WARNING)) + \")\")",
    "        params = frappe.get_doc(PARAMS)",
    "        params.set(WARNING, 8)",
    "        params.save()",
    "        settings = frappe.get_doc(\"Manufacturing Settings\")",
    "        settings.disable_capacity_planning = 1",
    "        settings.save()",
    "",
    "        # ---------------- 2. a Job Order with three operations on three machine groups ----------------",
    "        MILLS = \"CHK45 MILL \" + RUN",
    "        LATHES = \"CHK45 LATHE \" + RUN",
    "        GRINDERS = \"CHK45 GRIND \" + RUN",
    "        ops = [[\"CHK45 Milling \" + RUN, \"CHK45 MILL-01 \" + RUN, MILLS], [\"CHK45 Turning \" + RUN, \"CHK45 LATHE-01 \" + RUN, LATHES], [\"CHK45 Grinding \" + RUN, \"CHK45 GRIND-01 \" + RUN, GRINDERS]]",
    "        for row in ops:",
    "            frappe.get_doc({\"doctype\": \"Workstation Type\", \"workstation_type\": row[2]}).insert()",
    "            frappe.get_doc({\"doctype\": \"Workstation\", \"workstation_name\": row[1], \"workstation_type\": row[2]}).insert()",
    "            frappe.get_doc({\"doctype\": \"Operation\", \"name\": row[0], \"workstation\": row[1]}).insert()",
    "        FG = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK45-FG-\" + RUN, \"item_name\": \"CHK45 FG \" + RUN, \"item_group\": \"Finished Goods\", \"stock_uom\": \"Nos\", \"is_stock_item\": 1, \"is_sales_item\": 0}).insert().name",
    "        BO = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK45-BO-\" + RUN, \"item_name\": \"CHK45 Bought-out \" + RUN, \"item_group\": \"Bought-Out Components\", \"stock_uom\": \"Nos\", \"is_stock_item\": 1, \"is_sales_item\": 0, \"valuation_rate\": 10}).insert().name",
    "        bom = frappe.get_doc({\"doctype\": \"BOM\", \"item\": FG, \"company\": company, \"quantity\": 1, \"is_active\": 1, \"is_default\": 1, \"with_operations\": 1,",
    "                              \"currency\": frappe.db.get_value(\"Company\", company, \"default_currency\"), \"items\": [{\"item_code\": BO, \"qty\": 1, \"rate\": 10}],",
    "                              \"operations\": [{\"operation\": r[0], \"workstation\": r[1], \"time_in_mins\": 6} for r in ops]}).insert()",
    "        bom.submit()",
    "        wo = frappe.get_doc({\"doctype\": \"Work Order\", \"production_item\": FG, \"bom_no\": bom.name, \"qty\": 10, \"stock_uom\": \"Nos\", \"company\": company, \"skip_transfer\": 1,",
    "                             \"fg_warehouse\": wh(\"FG Stores\"), \"planned_start_date\": frappe.utils.add_days(frappe.utils.now(), -3), \"transfer_material_against\": \"Work Order\"})",
    "        wo.get_items_and_operations_from_bom()",
    "        wo.insert()",
    "        wo.submit()",
    "        cards = {}",
    "        for c in frappe.get_all(\"Job Card\", filters={\"work_order\": wo.name}, fields=[\"name\", \"operation\"]):",
    "            cards[c.operation] = c.name",
    "        check(len(cards) == 3, \"2. Job Order \" + wo.name + \" has 3 Job Cards: milling, turning, grinding (\" + \", \".join(sorted(cards.values())) + \")\")",
    "",
    "",
    "        def log(card, start, end, qty):",
    "            frappe.get_doc({\"doctype\": \"Job Card Time Log\", \"parent\": card, \"parenttype\": \"Job Card\", \"parentfield\": \"time_logs\", \"from_time\": start, \"to_time\": end,",
    "                            \"completed_qty\": qty, \"time_in_mins\": (end - start).total_seconds() / 60}).db_insert()",
    "",
    "",
    "        # the shift entries' blocks, as they land on the Job Cards (written directly here: the report only reads them)",
    "        log(cards[ops[0][0]], at(\"08:00\"), at(\"10:00\"), 6)",
    "        log(cards[ops[0][0]], at(\"10:00\"), at(\"12:00\"), 4)  # milling 10 of 10: finished 12:00",
    "        log(cards[ops[1][0]], at(\"22:00\"), at(\"23:00\"), 10)  # turning started 22:00: waited 10 h; finished 23:00",
    "        print(\"INFO  \" + DAY + \": milling 08:00-12:00 (10 of 10), turning 22:00-23:00 (10 of 10), grinding not started\")",
    "",
    "        # ---------------- 3. the report ----------------",
    "        filters = {\"job_order\": wo.name, \"from_date\": frappe.utils.add_days(today, -7), \"to_date\": today}",
    "        out = run_report(filters)",
    "        groups = out.get(\"result\") or []",
    "        lathe = [g for g in groups if g.get(\"workstation_type\") == LATHES]",
    "        grind = [g for g in groups if g.get(\"workstation_type\") == GRINDERS]",
    "        for g in groups:",
    "            print(\"INFO  \" + str(g.get(\"rank\")) + \". \" + str(g.get(\"workstation_type\")) + \": waits \" + str(g.get(\"waits\")) + \", average \" + str(g.get(\"average_hours\")) + \" h, waiting now \"",
    "                  + str(g.get(\"waiting_now\")) + \" (oldest \" + str(g.get(\"oldest_waiting_hours\")) + \" h), run \" + str(g.get(\"run_hours\")) + \" h\")",
    "        check(bool(lathe) and lathe[0].get(\"waits\") == 1 and lathe[0].get(\"average_hours\") == 10, \"3. turning waited 10 h after milling finished (12:00 -> 22:00)\")",
    "        check(bool(lathe) and lathe[0].get(\"colour\") == \"red\" and lathe[0].get(\"bottleneck\") == 1 and lathe[0].get(\"rank\") == 1, \"3. \" + LATHES + \" is the bottleneck, red (10 h above the 8 h warning)\")",
    "        check(bool(lathe) and lathe[0].get(\"run_hours\") == 1, \"3. run hours on \" + LATHES + \": 1\")",
    "        check(bool(grind) and grind[0].get(\"waiting_now\") == 1 and grind[0].get(\"oldest_waiting_hours\") > 24 and grind[0].get(\"colour\") == \"orange\",",
    "              \"3. grinding is waiting now since 23:00 on \" + DAY + \" (\" + str(grind[0].get(\"oldest_waiting_hours\") if grind else \"-\") + \" h), orange\")",
    "        check(not [g for g in groups if g.get(\"workstation_type\") == MILLS], \"3. milling (the first operation) has no wait\")",
    "        check(\"Bottleneck: \" + LATHES in str(out.get(\"message\")), \"3. the line above the report -> \" + str(out.get(\"message\"))[:200])",
    "        out = run_report(dict(filters, show=\"Operations\"))",
    "        rows = out.get(\"result\") or []",
    "        states = [str(r.get(\"operation\")) + \": \" + str(r.get(\"state_text\")) + \" \" + str(r.get(\"hours\")) + \" h\" for r in rows]",
    "        print(\"INFO  operations: \" + \"; \".join(states))",
    "        check(len(rows) == 2 and \"Waiting now\" in [r.get(\"state_text\") for r in rows] and \"Waited\" in [r.get(\"state_text\") for r in rows], \"3. 'Show: Operations' lists turning (waited) and grinding (waiting now)\")",
    "",
    "        # ---------------- 4. an overlap, and the setting ----------------",
    "        log(cards[ops[2][0]], at(\"22:30\"), at(\"23:30\"), 4)  # grinding started 22:30, before turning finished 23:00",
    "        out = run_report(dict(filters, show=\"Operations\"))",
    "        grinding = [r for r in out.get(\"result\") or [] if r.get(\"operation\") == ops[2][0]]",
    "        check(bool(grinding) and grinding[0].get(\"state_text\") == \"Overlapped\" and grinding[0].get(\"hours\") == 0, \"4. grinding started before turning finished: 'Overlapped', no wait\")",
    "        params = frappe.get_doc(PARAMS)",
    "        params.set(WARNING, 12)",
    "        params.save()",
    "        out = run_report(filters)",
    "        lathe = [g for g in out.get(\"result\") or [] if g.get(\"workstation_type\") == LATHES]",
    "        check(bool(lathe) and lathe[0].get(\"colour\") != \"red\", \"4. with Wait Warning Hours = 12 the 10 h wait is no longer red\")",
    "",
    "",
    "        def bad_warning():",
    "            p = frappe.get_doc(PARAMS)",
    "            p.set(WARNING, 0)",
    "            p.save()",
    "",
    "",
    "        refused(\"4. Wait Warning Hours of 0 is refused\", bad_warning, \"Bottleneck: Wait Warning Hours\")",
    "",
    "        print(\"\")",
    "        print(\"RESULT: \" + str(len(passed)) + \" passed, \" + str(len(failed)) + \" failed\")",
    "        print(\"Commit was left unticked, so nothing above was saved.\")",
    "        ALL_RESULTS.append([45, \"check_45_c3a_b4_bottleneck\", len(passed), len(failed), all_seconds(ALL_T), list(failed)])",
    "    except Exception as all_error:",
    "        all_text = frappe.utils.strip_html(str(all_error))[:400]",
    "        ALL_RESULTS.append([45, \"check_45_c3a_b4_bottleneck\", len(passed), len(failed) + 1, all_seconds(ALL_T), list(failed) + [\"CRASHED: \" + all_text]])",
    "    frappe.db.rollback()",
    "    all_note(\"RUNNING - Check 45 done\")",
    "",
    "# =====================================================================================================",
    "# Check 46: check_46_c3a_b5_ld_exposure",
    "# =====================================================================================================",
    "if FIRST <= 46 <= LAST:",
    "    print(\"CHECK 46  (check_46_c3a_b5_ld_exposure)\")",
    "    ALL_T = frappe.utils.now_datetime()",
    "    passed = []",
    "    failed = []",
    "    try:",
    "        # PEPL OS v0.46.0 - Check 46: C3a-B5 LD Exposure report - late days x contractual LD rate on every open Sales Order:",
    "        # LD so far, LD in the look-ahead days if nothing more is delivered, red / orange / green, by order and by line.",
    "        # Runs on 0.46.0 or later. System Console, Type = Python. Leave \"Commit\" UNTICKED: everything below is undone at the",
    "        # end. Then open the report in the browser: see the steps in the chat.",
    "        VERSION = \"0.46.0\"",
    "        PARAMS = \"PEPL System Parameters\"",
    "        REPORT = \"PEPL LD Exposure\"",
    "        AHEAD = \"custom_ld_look_ahead_days\"",
    "        passed = []",
    "        failed = []",
    "",
    "",
    "        def check(ok, label):",
    "            if ok:",
    "                passed.append(label)",
    "                print(\"PASS  \" + label)",
    "            else:",
    "                failed.append(label)",
    "                print(\"FAIL  \" + label)",
    "",
    "",
    "        def refused(label, action, words):",
    "            try:",
    "                action()",
    "                check(False, label + \" (it was accepted)\")",
    "            except Exception as e:",
    "                text = frappe.utils.strip_html(str(e))",
    "                check(words.lower() in text.lower(), label + \" -> \" + text[:200])",
    "",
    "",
    "        def version_parts(value):",
    "            return [int(part) for part in str(value or \"0\").split(\".\")[:3]]",
    "",
    "",
    "        def near(a, b):",
    "            return a is not None and abs(frappe.utils.flt(a) - frappe.utils.flt(b)) <= 0.011",
    "",
    "",
    "        def run_report(filters):",
    "            return frappe.call(\"frappe.desk.query_report.run\", report_name=REPORT, filters=filters)",
    "",
    "",
    "        RUN = frappe.utils.now().replace(\"-\", \"\").replace(\":\", \"\").replace(\" \", \"\").replace(\".\", \"\")[8:14]",
    "        print(\"INFO  run \" + RUN + \" (all test names end with it)\")",
    "        today = frappe.utils.today()",
    "        company = frappe.db.get_single_value(\"Global Defaults\", \"default_company\") or frappe.get_all(\"Company\", pluck=\"name\", limit=1)[0]",
    "",
    "",
    "        def wh(store):",
    "            return frappe.db.get_value(\"Warehouse\", {\"company\": company, \"warehouse_name\": store, \"is_group\": 0}, \"name\")",
    "",
    "",
    "        def day(offset):",
    "            return frappe.utils.add_days(today, offset)",
    "",
    "",
    "        # ---------------- 1. installed ----------------",
    "        apps = {a.app_name: a.app_version for a in frappe.get_all(\"Installed Application\", fields=[\"app_name\", \"app_version\"])}",
    "        check(version_parts(apps.get(\"pepl_os\")) >= version_parts(VERSION), \"1. pepl_os is \" + VERSION + \" or later (site has \" + str(apps.get(\"pepl_os\")) + \")\")",
    "        check(frappe.db.get_value(\"Report\", REPORT, \"report_type\") == \"Script Report\" and bool(frappe.get_all(\"Workspace Link\", filters={\"parent\": \"Production Command Centre\", \"link_to\": REPORT})),",
    "              \"1. report '\" + REPORT + \"' exists and is listed on the Production Command Centre\")",
    "        check(bool(frappe.get_meta(PARAMS).get_field(AHEAD)), \"1. System Parameters > Production > LD: Look-Ahead Days (this site: \" + str(frappe.db.get_single_value(PARAMS, AHEAD)) + \")\")",
    "        params = frappe.get_doc(PARAMS)",
    "        params.custom_ld_default_sectors = \"Railways\\nDefence\"",
    "        params.custom_ld_default_rate_percent = 0.5",
    "        params.custom_ld_default_period = \"Week\"",
    "        params.custom_ld_default_max_percent = 10",
    "        params.set(AHEAD, 7)",
    "        params.save()",
    "",
    "        # ---------------- 2. a customer, a part, four orders ----------------",
    "        # The part is a bought-out sales item with an 8-digit HSN code (India Compliance checks Sales Orders and Delivery Notes).",
    "        hsn = \"\"",
    "        if frappe.db.exists(\"DocType\", \"GST HSN Code\"):",
    "            codes = [c for c in frappe.get_all(\"GST HSN Code\", filters={\"name\": [\"like\", \"8483%\"]}, pluck=\"name\", limit=20) if len(c) == 8]",
    "            hsn = codes[0] if codes else \"\"",
    "        values = {\"doctype\": \"Item\", \"item_code\": \"CHK46-PART-\" + RUN, \"item_name\": \"CHK46 Part \" + RUN, \"item_group\": \"Bought-Out Components\", \"stock_uom\": \"Nos\", \"is_stock_item\": 1, \"is_sales_item\": 1 if hsn else 0, \"valuation_rate\": 50}",
    "        if hsn:",
    "            values[\"gst_hsn_code\"] = hsn",
    "        PART = frappe.get_doc(values).insert().name",
    "        receipt = frappe.get_doc({\"doctype\": \"Stock Entry\", \"stock_entry_type\": \"Material Receipt\", \"purpose\": \"Material Receipt\", \"company\": company, \"set_posting_time\": 1, \"posting_date\": day(-40),",
    "                                  \"items\": [{\"item_code\": PART, \"qty\": 100, \"t_warehouse\": wh(\"Bought-Out Stores\"), \"basic_rate\": 50}]}).insert()",
    "        receipt.submit()",
    "        groups = frappe.get_all(\"Customer Group\", filters={\"is_group\": 0}, pluck=\"name\", limit=1)",
    "        territories = frappe.get_all(\"Territory\", filters={\"is_group\": 0}, pluck=\"name\", limit=1)",
    "        customer = frappe.get_doc({\"doctype\": \"Customer\", \"customer_name\": \"CHK46 Customer \" + RUN, \"customer_type\": \"Company\",",
    "                                   \"customer_group\": groups[0] if groups else None, \"territory\": territories[0] if territories else None}).insert().name",
    "",
    "",
    "        def order(sector, ordered_days_ago, due_in):",
    "            doc = frappe.get_doc({\"doctype\": \"Sales Order\", \"customer\": customer, \"company\": company, \"custom_sector\": sector,",
    "                                  \"transaction_date\": day(-ordered_days_ago), \"delivery_date\": day(due_in),",
    "                                  \"items\": [{\"item_code\": PART, \"qty\": 10, \"rate\": 100, \"warehouse\": wh(\"Bought-Out Stores\"), \"delivery_date\": day(due_in)}]}).insert()",
    "            doc.submit()",
    "            return doc.name",
    "",
    "",
    "        late = order(\"Railways\", 30, -10)  # 10 days late",
    "        soon = order(\"Railways\", 5, 3)  # due in 3 days",
    "        fine = order(\"Railways\", 5, 30)  # due in 30 days",
    "        private = order(\"Private\", 30, -10)  # late, but no LD clause",
    "        print(\"INFO  orders of \" + customer + \": late \" + late + \" (due 10 days ago), soon \" + soon + \" (due in 3 days), on time \" + fine + \" (due in 30 days), no LD \" + private)",
    "",
    "        # ---------------- 3. the report, by order ----------------",
    "        out = run_report({\"customer\": customer, \"as_on\": today})",
    "        rows = out.get(\"result\") or []",
    "        by = {}",
    "        for r in rows:",
    "            by[r.get(\"sales_order\")] = r",
    "        for r in rows:",
    "            print(\"INFO  \" + str(r.get(\"sales_order\")) + \": \" + str(r.get(\"terms\")) + \", days late \" + str(r.get(\"days_late\")) + \", LD so far \" + str(r.get(\"ld_now\")) + \", in 7 days \"",
    "                  + str(r.get(\"ld_ahead\")) + \" (\" + str(r.get(\"colour\")) + \")\")",
    "        check(late in by and near(by[late].get(\"ld_now\"), 10) and by[late].get(\"days_late\") == 10, \"3. \" + late + \": 10 days late = 2 weeks: 1000 x 0.5 % x 2 = 10 so far\")",
    "        check(late in by and near(by[late].get(\"ld_ahead\"), 15) and near(by[late].get(\"ld_added\"), 5) and by[late].get(\"colour\") == \"red\", \"3. ... in 7 days (17 days = 3 weeks) 15, 5 more - red\")",
    "        check(late in by and near(by[late].get(\"cap_amount\"), 100) and near(by[late].get(\"cap_used\"), 10), \"3. ... cap 10 % of 1000 = 100, 10 % of it used\")",
    "        check(soon in by and near(by[soon].get(\"ld_now\"), 0) and near(by[soon].get(\"ld_ahead\"), 5) and by[soon].get(\"colour\") == \"orange\", \"3. \" + soon + \": no LD yet, 5 if not delivered in 7 days - orange\")",
    "        check(fine in by and near(by[fine].get(\"ld_ahead\"), 0) and by[fine].get(\"colour\") == \"green\", \"3. \" + fine + \": due in 30 days - green\")",
    "        check(private not in by, \"3. \" + private + \" (no LD clause) is left out while 'Only orders with LD terms' is ticked\")",
    "        check(rows and rows[0].get(\"sales_order\") == late, \"3. the order with the most LD comes first\")",
    "        check(\"on 1 order(s)\" in str(out.get(\"message\")) and \"1 more order(s) start LD\" in str(out.get(\"message\")), \"3. the line above the report -> \" + str(out.get(\"message\")))",
    "        out = run_report({\"customer\": customer, \"as_on\": today, \"only_ld\": 0})",
    "        grey = [r for r in out.get(\"result\") or [] if r.get(\"sales_order\") == private]",
    "        check(bool(grey) and grey[0].get(\"terms\") == \"no LD clause\" and grey[0].get(\"colour\") == \"gray\", \"3. unticked: \" + private + \" shows grey, 'no LD clause'\")",
    "",
    "        # ---------------- 4. by line, a late part delivery, and the setting ----------------",
    "        dn = frappe.get_doc({\"doctype\": \"Delivery Note\", \"customer\": customer, \"company\": company, \"posting_date\": today,",
    "                             \"items\": [{\"item_code\": PART, \"qty\": 4, \"rate\": 100, \"warehouse\": wh(\"Bought-Out Stores\"), \"against_sales_order\": late,",
    "                                        \"so_detail\": frappe.get_doc(\"Sales Order\", late).items[0].name}]}).insert()",
    "        dn.submit()",
    "        out = run_report({\"sales_order\": late, \"as_on\": today, \"show\": \"Lines\"})",
    "        line = (out.get(\"result\") or [{}])[0]",
    "        check(line.get(\"delivered\") == 4 and line.get(\"pending\") == 6 and near(line.get(\"ld_now\"), 10) and near(line.get(\"ld_ahead\"), 13),",
    "              \"4. 4 delivered today (late), 6 pending: 10 so far; in 7 days 4 + 600 x 0.5 % x 3 = 13 (by line)\")",
    "        params = frappe.get_doc(PARAMS)",
    "        params.set(AHEAD, 2)",
    "        params.save()",
    "        out = run_report({\"sales_order\": soon, \"as_on\": today})",
    "        row = (out.get(\"result\") or [{}])[0]",
    "        check(near(row.get(\"ld_ahead\"), 0) and row.get(\"colour\") == \"green\", \"4. with LD: Look-Ahead Days = 2, \" + soon + \" (due in 3 days) is green\")",
    "",
    "",
    "        def bad_ahead():",
    "            p = frappe.get_doc(PARAMS)",
    "            p.set(AHEAD, 400)",
    "            p.save()",
    "",
    "",
    "        refused(\"4. LD: Look-Ahead Days of 400 is refused\", bad_ahead, \"LD: Look-Ahead Days\")",
    "",
    "        print(\"\")",
    "        print(\"RESULT: \" + str(len(passed)) + \" passed, \" + str(len(failed)) + \" failed\")",
    "        print(\"Commit was left unticked, so nothing above was saved.\")",
    "        ALL_RESULTS.append([46, \"check_46_c3a_b5_ld_exposure\", len(passed), len(failed), all_seconds(ALL_T), list(failed)])",
    "    except Exception as all_error:",
    "        all_text = frappe.utils.strip_html(str(all_error))[:400]",
    "        ALL_RESULTS.append([46, \"check_46_c3a_b5_ld_exposure\", len(passed), len(failed) + 1, all_seconds(ALL_T), list(failed) + [\"CRASHED: \" + all_text]])",
    "    frappe.db.rollback()",
    "    all_note(\"RUNNING - Check 46 done\")",
    "",
    "# =====================================================================================================",
    "# Check 47: check_47_c3a_b6_rejection_scrap",
    "# =====================================================================================================",
    "if FIRST <= 47 <= LAST:",
    "    print(\"CHECK 47  (check_47_c3a_b6_rejection_scrap)\")",
    "    ALL_T = frappe.utils.now_datetime()",
    "    passed = []",
    "    failed = []",
    "    try:",
    "        # PEPL OS v0.47.0 - Check 47: C3a-B6 shift-entry rejections go to the Scrap Register by themselves - a submitted",
    "        # entry's rejected pieces become a Scrap Weighment (source Rejection, kg = pieces x weight per unit, at the scrap",
    "        # rate, into Scrap Yard); missing weight / scrap item / rate gives Stores a ToDo; cancelling the entry takes it back.",
    "        # Runs on 0.47.0 or later. System Console, Type = Python. Leave \"Commit\" UNTICKED: everything below is undone at the",
    "        # end. Then look at the screens in the browser: see the steps in the chat.",
    "        VERSION = \"0.47.0\"",
    "        PARAMS = \"PEPL System Parameters\"",
    "        SPR = \"PEPL Shift Production Entry\"",
    "        WEIGHMENT = \"PEPL Scrap Weighment\"",
    "        RULE = \"PRD-REJECT-SCRAP\"",
    "        passed = []",
    "        failed = []",
    "",
    "",
    "        def check(ok, label):",
    "            if ok:",
    "                passed.append(label)",
    "                print(\"PASS  \" + label)",
    "            else:",
    "                failed.append(label)",
    "                print(\"FAIL  \" + label)",
    "",
    "",
    "        def version_parts(value):",
    "            return [int(part) for part in str(value or \"0\").split(\".\")[:3]]",
    "",
    "",
    "        RUN = frappe.utils.now().replace(\"-\", \"\").replace(\":\", \"\").replace(\" \", \"\").replace(\".\", \"\")[8:14]",
    "        print(\"INFO  run \" + RUN + \" (all test names end with it)\")",
    "        today = frappe.utils.today()",
    "        yesterday = frappe.utils.add_days(today, -1)",
    "        company = frappe.db.get_single_value(\"Global Defaults\", \"default_company\") or frappe.get_all(\"Company\", pluck=\"name\", limit=1)[0]",
    "",
    "",
    "        def wh(store):",
    "            return frappe.db.get_value(\"Warehouse\", {\"company\": company, \"warehouse_name\": store, \"is_group\": 0}, \"name\")",
    "",
    "",
    "        # ---------------- 1. installed ----------------",
    "        apps = {a.app_name: a.app_version for a in frappe.get_all(\"Installed Application\", fields=[\"app_name\", \"app_version\"])}",
    "        check(version_parts(apps.get(\"pepl_os\")) >= version_parts(VERSION), \"1. pepl_os is \" + VERSION + \" or later (site has \" + str(apps.get(\"pepl_os\")) + \")\")",
    "        pmeta = frappe.get_meta(PARAMS)",
    "        check(bool(pmeta.get_field(\"custom_rejections_to_scrap\")) and bool(pmeta.get_field(\"custom_rejection_scrap_item\")),",
    "              \"1. System Parameters > Production > Rejections to Scrap: on/off (\" + str(frappe.db.get_single_value(PARAMS, \"custom_rejections_to_scrap\")) + \") and Rejection Scrap Item (\"",
    "              + str(frappe.db.get_single_value(PARAMS, \"custom_rejection_scrap_item\") or \"empty\") + \")\")",
    "        check(bool(frappe.get_meta(\"Item\").get_field(\"custom_rejection_scrap_item\")) and bool(frappe.get_meta(WEIGHMENT).get_field(\"shift_production_entry\")),",
    "              \"1. Item has 'Scrap Item when Rejected'; Scrap Weighment has 'Shift Production Entry' and 'Rejected Pieces'\")",
    "        params = frappe.get_doc(PARAMS)",
    "        params.custom_rejections_to_scrap = 1",
    "        params.custom_rejection_scrap_item = None",
    "        params.enable_operational_todos = 1",
    "        if not params.get(\"custom_stores_notification_owner\"):",
    "            params.custom_stores_notification_owner = \"Administrator\"",
    "        params.skill_check_mode = \"Advisory\"",
    "        params.custom_spr_tool_photo_required = 0",
    "        params.custom_spr_max_unaccounted_minutes = 15",
    "        params.save()",
    "        settings = frappe.get_doc(\"Manufacturing Settings\")",
    "        settings.disable_capacity_planning = 1",
    "        settings.overproduction_percentage_for_work_order = 0",
    "        settings.save()",
    "",
    "        # ---------------- 2. a scrap item with a rate, a part that weighs 0.25 kg, a Job Card ----------------",
    "        BRASS = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK47-SCRAP-\" + RUN, \"item_name\": \"CHK47 Brass Turnings \" + RUN, \"item_group\": \"Brass Scrap\", \"stock_uom\": \"Kg\",",
    "                                \"is_stock_item\": 1, \"is_sales_item\": 0, \"is_purchase_item\": 0}).insert().name",
    "        frappe.get_doc({\"doctype\": \"PEPL Scrap Rate\", \"scrap_item\": BRASS, \"rate\": 40, \"effective_from\": frappe.utils.add_days(today, -30)}).insert()",
    "        MILL = \"CHK47 MILL-01 \" + RUN",
    "        DAY = \"CHK47 Day \" + RUN",
    "        OP = \"CHK47-OP-\" + RUN",
    "        NO_LOAD = \"CHK47 No Load \" + RUN",
    "        frappe.get_doc({\"doctype\": \"Workstation\", \"workstation_name\": MILL}).insert()",
    "        frappe.get_doc({\"doctype\": \"PEPL Shift\", \"shift_name\": DAY, \"start_time\": \"08:00:00\", \"end_time\": \"16:30:00\", \"break_minutes\": 30}).insert()",
    "        pin = \"1\" * int(frappe.db.get_single_value(PARAMS, \"custom_operator_pin_digits\") or 4)",
    "        frappe.get_doc({\"doctype\": \"PEPL Operator\", \"employee_code\": OP, \"operator_name\": \"Ramesh \" + RUN, \"pin\": pin}).insert()",
    "        frappe.get_doc({\"doctype\": \"PEPL Downtime Category\", \"category_name\": NO_LOAD, \"stop_type\": \"Planned\", \"is_breakdown\": 0}).insert()",
    "        FG = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK47-FG-\" + RUN, \"item_name\": \"CHK47 FG \" + RUN, \"item_group\": \"Finished Goods\", \"stock_uom\": \"Nos\", \"is_stock_item\": 1,",
    "                             \"is_sales_item\": 0, \"weight_per_unit\": 0.25, \"weight_uom\": \"Kg\", \"custom_rejection_scrap_item\": BRASS}).insert().name",
    "        BO = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK47-BO-\" + RUN, \"item_name\": \"CHK47 Bought-out \" + RUN, \"item_group\": \"Bought-Out Components\", \"stock_uom\": \"Nos\",",
    "                             \"is_stock_item\": 1, \"is_sales_item\": 0, \"valuation_rate\": 10}).insert().name",
    "        TURNING = \"CHK47 Turning \" + RUN",
    "        frappe.get_doc({\"doctype\": \"Operation\", \"name\": TURNING, \"workstation\": MILL}).insert()",
    "        bom = frappe.get_doc({\"doctype\": \"BOM\", \"item\": FG, \"company\": company, \"quantity\": 1, \"is_active\": 1, \"is_default\": 1, \"with_operations\": 1,",
    "                              \"currency\": frappe.db.get_value(\"Company\", company, \"default_currency\"), \"items\": [{\"item_code\": BO, \"qty\": 1, \"rate\": 10}],",
    "                              \"operations\": [{\"operation\": TURNING, \"workstation\": MILL, \"time_in_mins\": 6}]}).insert()",
    "        bom.submit()",
    "        wo = frappe.get_doc({\"doctype\": \"Work Order\", \"production_item\": FG, \"bom_no\": bom.name, \"qty\": 40, \"stock_uom\": \"Nos\", \"company\": company, \"skip_transfer\": 1,",
    "                             \"fg_warehouse\": wh(\"FG Stores\"), \"planned_start_date\": frappe.utils.now(), \"transfer_material_against\": \"Work Order\"})",
    "        wo.get_items_and_operations_from_bom()",
    "        wo.insert()",
    "        wo.submit()",
    "        CARD = frappe.get_all(\"Job Card\", filters={\"work_order\": wo.name}, pluck=\"name\")[0]",
    "        print(\"INFO  \" + FG + \" weighs 0.25 kg; when rejected it becomes \" + BRASS + \" at 40 a kg; Job Card \" + CARD)",
    "",
    "",
    "        def entry(rejected, on):",
    "            doc = frappe.get_doc({\"doctype\": SPR, \"posting_date\": on, \"shift\": DAY, \"workstation\": MILL, \"operator\": OP, \"company\": company})",
    "            doc.append(\"production\", {\"job_card\": CARD, \"from_time\": \"08:00\", \"to_time\": \"10:00\", \"good_qty\": 8, \"rejected_qty\": rejected, \"rejection_reason\": \"Undersize\"})",
    "            doc.append(\"downtime\", {\"downtime_category\": NO_LOAD, \"from_time\": \"10:00\", \"to_time\": \"16:30\"})",
    "            doc.insert()",
    "            doc.submit()",
    "            return doc.name",
    "",
    "",
    "        def todos(name, status):",
    "            return frappe.get_all(\"ToDo\", filters={\"reference_type\": SPR, \"reference_name\": name, \"status\": status, \"description\": [\"like\", \"%\" + RULE + \"%\"]}, pluck=\"description\")",
    "",
    "",
    "        # ---------------- 3. submitted entry -> Scrap Weighment ----------------",
    "        first = entry(4, yesterday)",
    "        ws = frappe.get_all(WEIGHMENT, filters={\"shift_production_entry\": first, \"docstatus\": 1}, fields=[\"name\", \"source\", \"scrap_item\", \"net_kg\", \"rate_applied\", \"amount\", \"rejected_pieces\", \"stock_entry\", \"warehouse\"])",
    "        w = ws[0] if ws else {}",
    "        print(\"INFO  \" + first + \": 8 good, 4 rejected -> \" + str(w.get(\"name\")) + \" \" + str(w.get(\"net_kg\")) + \" kg \" + str(w.get(\"scrap_item\")) + \" at \" + str(w.get(\"rate_applied\")) + \" = \" + str(w.get(\"amount\")))",
    "        check(len(ws) == 1 and w.get(\"source\") == \"Rejection\" and w.get(\"scrap_item\") == BRASS and w.get(\"rejected_pieces\") == 4, \"3. the 4 rejected pieces became Scrap Weighment \" + str(w.get(\"name\")) + \" (source Rejection, \" + BRASS + \")\")",
    "        check(abs(frappe.utils.flt(w.get(\"net_kg\")) - 1) < 0.001 and frappe.utils.flt(w.get(\"amount\")) == 40, \"3. weight 4 x 0.25 = 1 kg, at 40 a kg = 40\")",
    "        check(bool(w.get(\"stock_entry\")) and frappe.db.get_value(\"Stock Entry\", w.get(\"stock_entry\"), \"docstatus\") == 1 and w.get(\"warehouse\") == wh(\"Scrap Yard\"),",
    "              \"3. it posted Material Receipt \" + str(w.get(\"stock_entry\")) + \" into \" + str(w.get(\"warehouse\")))",
    "        panel = frappe.call(\"pepl_os.pepl_production.spr.get_spr_panel\", name=first).get(\"rows\") or []",
    "        line = [r.get(\"text\") for r in panel if \"Scrap Weighment\" in r.get(\"text\")]",
    "        check(bool(line), \"3. the entry's Shift panel says -> \" + (line[0] if line else \"nothing\"))",
    "",
    "        # ---------------- 4. missing weight -> a ToDo for Stores ----------------",
    "        frappe.db.set_value(\"Item\", FG, \"weight_per_unit\", 0)",
    "        second = entry(3, frappe.utils.add_days(today, -2))  # another day: one machine, one shift, no overlap",
    "        check(not frappe.get_all(WEIGHMENT, filters={\"shift_production_entry\": second}), \"4. without a weight per unit nothing is posted\")",
    "        open_todos = todos(second, \"Open\")",
    "        check(bool(open_todos) and \"3 rejected piece(s)\" in open_todos[0] and \"weight per unit\" in open_todos[0], \"4. Stores gets a ToDo -> \" + (open_todos[0].split(\"\\n\")[-1][:220] if open_todos else \"none\"))",
    "",
    "        # ---------------- 5. cancelling takes it back ----------------",
    "        frappe.get_doc(SPR, first).cancel()",
    "        check(frappe.db.get_value(WEIGHMENT, w.get(\"name\"), \"docstatus\") == 2 and frappe.db.get_value(\"Stock Entry\", w.get(\"stock_entry\"), \"docstatus\") == 2,",
    "              \"5. cancelling \" + first + \" cancels its weighment and the scrap receipt\")",
    "        frappe.get_doc(SPR, second).cancel()",
    "        check(not todos(second, \"Open\") and bool(todos(second, \"Cancelled\")), \"5. cancelling \" + second + \" closes the Stores ToDo\")",
    "",
    "        print(\"\")",
    "        print(\"RESULT: \" + str(len(passed)) + \" passed, \" + str(len(failed)) + \" failed\")",
    "        print(\"Commit was left unticked, so nothing above was saved.\")",
    "        ALL_RESULTS.append([47, \"check_47_c3a_b6_rejection_scrap\", len(passed), len(failed), all_seconds(ALL_T), list(failed)])",
    "    except Exception as all_error:",
    "        all_text = frappe.utils.strip_html(str(all_error))[:400]",
    "        ALL_RESULTS.append([47, \"check_47_c3a_b6_rejection_scrap\", len(passed), len(failed) + 1, all_seconds(ALL_T), list(failed) + [\"CRASHED: \" + all_text]])",
    "    frappe.db.rollback()",
    "    all_note(\"RUNNING - Check 47 done\")",
    "",
    "# =====================================================================================================",
    "# Check 48: check_48_c3a_b7_standup_exceptions",
    "# =====================================================================================================",
    "if FIRST <= 48 <= LAST:",
    "    print(\"CHECK 48  (check_48_c3a_b7_standup_exceptions)\")",
    "    ALL_T = frappe.utils.now_datetime()",
    "    passed = []",
    "    failed = []",
    "    try:",
    "        # PEPL OS v0.48.0 - Check 48: C3a-B7 the Daily Stand-up, exception-only - only what needs attention (machines below",
    "        # the OEE target, unplanned stops of at least the minimum, machines without an entry, delivery risk, LD running,",
    "        # work waiting, job work overdue, rejections to weigh), numbered as shown; untick the setting for the full page.",
    "        # Runs on 0.48.0 or later. System Console, Type = Python. Leave \"Commit\" UNTICKED: everything below is undone at the",
    "        # end. The test day is 150 days ago, so this bench's own shift entries do not mix in.",
    "        VERSION = \"0.48.0\"",
    "        PARAMS = \"PEPL System Parameters\"",
    "        SPR = \"PEPL Shift Production Entry\"",
    "        STANDUP = \"PEPL Daily Standup\"",
    "        BUILD = \"pepl_os.pepl_production.standup.build_standup_now\"",
    "        passed = []",
    "        failed = []",
    "",
    "",
    "        def check(ok, label):",
    "            if ok:",
    "                passed.append(label)",
    "                print(\"PASS  \" + label)",
    "            else:",
    "                failed.append(label)",
    "                print(\"FAIL  \" + label)",
    "",
    "",
    "        def refused(label, action, words):",
    "            try:",
    "                action()",
    "                check(False, label + \" (it was accepted)\")",
    "            except Exception as e:",
    "                text = frappe.utils.strip_html(str(e))",
    "                check(words.lower() in text.lower(), label + \" -> \" + text[:200])",
    "",
    "",
    "        def version_parts(value):",
    "            return [int(part) for part in str(value or \"0\").split(\".\")[:3]]",
    "",
    "",
    "        RUN = frappe.utils.now().replace(\"-\", \"\").replace(\":\", \"\").replace(\" \", \"\").replace(\".\", \"\")[8:14]",
    "        print(\"INFO  run \" + RUN + \" (all test names end with it)\")",
    "        today = frappe.utils.today()",
    "        D = frappe.utils.add_days(today, -150)",
    "        company = frappe.db.get_single_value(\"Global Defaults\", \"default_company\") or frappe.get_all(\"Company\", pluck=\"name\", limit=1)[0]",
    "",
    "",
    "        def wh(store):",
    "            return frappe.db.get_value(\"Warehouse\", {\"company\": company, \"warehouse_name\": store, \"is_group\": 0}, \"name\")",
    "",
    "",
    "        def settings(exception_only, min_stop, target):",
    "            p = frappe.get_doc(PARAMS)",
    "            p.custom_standup_exception_only = exception_only",
    "            p.custom_standup_min_stop_minutes = min_stop",
    "            p.custom_oee_target_percent = target",
    "            p.save()",
    "",
    "",
    "        def page():",
    "            name = frappe.call(BUILD, day=D).get(\"name\")",
    "            return frappe.get_doc(STANDUP, name)",
    "",
    "",
    "        # ---------------- 1. installed ----------------",
    "        apps = {a.app_name: a.app_version for a in frappe.get_all(\"Installed Application\", fields=[\"app_name\", \"app_version\"])}",
    "        check(version_parts(apps.get(\"pepl_os\")) >= version_parts(VERSION), \"1. pepl_os is \" + VERSION + \" or later (site has \" + str(apps.get(\"pepl_os\")) + \")\")",
    "        pmeta = frappe.get_meta(PARAMS)",
    "        check(bool(pmeta.get_field(\"custom_standup_exception_only\")) and bool(pmeta.get_field(\"custom_standup_min_stop_minutes\")),",
    "              \"1. System Parameters > Production: Stand-up: Exception-Only (\" + str(frappe.db.get_single_value(PARAMS, \"custom_standup_exception_only\")) + \"), Minimum Stop Minutes (\"",
    "              + str(frappe.db.get_single_value(PARAMS, \"custom_standup_min_stop_minutes\")) + \")\")",
    "        smeta = frappe.get_meta(STANDUP)",
    "        check(bool(smeta.get_field(\"exceptions\")) and bool(smeta.get_field(\"all_clear\")), \"1. the Daily Stand-up record has 'Things Needing Attention' and 'All Clear'\")",
    "        p = frappe.get_doc(PARAMS)",
    "        p.skill_check_mode = \"Advisory\"",
    "        p.custom_spr_tool_photo_required = 0",
    "        p.custom_spr_max_unaccounted_minutes = 15",
    "        p.save()",
    "        settings(1, 30, 85)",
    "        s = frappe.get_doc(\"Manufacturing Settings\")",
    "        s.disable_capacity_planning = 1",
    "        s.save()",
    "",
    "        # ---------------- 2. a day on the shop floor, 150 days ago ----------------",
    "        MILL = \"CHK48 MILL-01 \" + RUN",
    "        LATHE = \"CHK48 LATHE-01 \" + RUN",
    "        DAY = \"CHK48 Day \" + RUN",
    "        OP = \"CHK48-OP-\" + RUN",
    "        NO_LOAD = \"CHK48 No Load \" + RUN",
    "        SPINDLE = \"CHK48 Spindle \" + RUN",
    "        frappe.get_doc({\"doctype\": \"Workstation\", \"workstation_name\": MILL}).insert()",
    "        frappe.get_doc({\"doctype\": \"Workstation\", \"workstation_name\": LATHE}).insert()",
    "        frappe.get_doc({\"doctype\": \"PEPL Shift\", \"shift_name\": DAY, \"start_time\": \"08:00:00\", \"end_time\": \"16:30:00\", \"break_minutes\": 30}).insert()",
    "        pin = \"1\" * int(frappe.db.get_single_value(PARAMS, \"custom_operator_pin_digits\") or 4)",
    "        frappe.get_doc({\"doctype\": \"PEPL Operator\", \"employee_code\": OP, \"operator_name\": \"Ramesh \" + RUN, \"pin\": pin}).insert()",
    "        frappe.get_doc({\"doctype\": \"PEPL Downtime Category\", \"category_name\": NO_LOAD, \"stop_type\": \"Planned\", \"is_breakdown\": 0}).insert()",
    "        frappe.get_doc({\"doctype\": \"PEPL Downtime Category\", \"category_name\": SPINDLE, \"stop_type\": \"Unplanned\", \"is_breakdown\": 1}).insert()",
    "        FG = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK48-FG-\" + RUN, \"item_name\": \"CHK48 FG \" + RUN, \"item_group\": \"Finished Goods\", \"stock_uom\": \"Nos\", \"is_stock_item\": 1, \"is_sales_item\": 0}).insert().name",
    "        BO = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK48-BO-\" + RUN, \"item_name\": \"CHK48 Bought-out \" + RUN, \"item_group\": \"Bought-Out Components\", \"stock_uom\": \"Nos\", \"is_stock_item\": 1,",
    "                             \"is_sales_item\": 0, \"valuation_rate\": 10}).insert().name",
    "        TURNING = \"CHK48 Turning \" + RUN",
    "        frappe.get_doc({\"doctype\": \"Operation\", \"name\": TURNING, \"workstation\": MILL}).insert()",
    "        bom = frappe.get_doc({\"doctype\": \"BOM\", \"item\": FG, \"company\": company, \"quantity\": 1, \"is_active\": 1, \"is_default\": 1, \"with_operations\": 1,",
    "                              \"currency\": frappe.db.get_value(\"Company\", company, \"default_currency\"), \"items\": [{\"item_code\": BO, \"qty\": 1, \"rate\": 10}],",
    "                              \"operations\": [{\"operation\": TURNING, \"workstation\": MILL, \"time_in_mins\": 6}]}).insert()",
    "        bom.submit()",
    "        wo = frappe.get_doc({\"doctype\": \"Work Order\", \"production_item\": FG, \"bom_no\": bom.name, \"qty\": 10, \"stock_uom\": \"Nos\", \"company\": company, \"skip_transfer\": 1,",
    "                             \"fg_warehouse\": wh(\"FG Stores\"), \"planned_start_date\": frappe.utils.now(), \"transfer_material_against\": \"Work Order\"})",
    "        wo.get_items_and_operations_from_bom()",
    "        wo.insert()",
    "        wo.submit()",
    "        CARD = frappe.get_all(\"Job Card\", filters={\"work_order\": wo.name}, pluck=\"name\")[0]",
    "        mill = frappe.get_doc({\"doctype\": SPR, \"posting_date\": D, \"shift\": DAY, \"workstation\": MILL, \"operator\": OP, \"company\": company})",
    "        mill.append(\"production\", {\"job_card\": CARD, \"from_time\": \"08:00\", \"to_time\": \"12:00\", \"good_qty\": 10})",
    "        mill.append(\"downtime\", {\"downtime_category\": SPINDLE, \"from_time\": \"12:00\", \"to_time\": \"13:00\"})",
    "        mill.append(\"downtime\", {\"downtime_category\": NO_LOAD, \"from_time\": \"13:00\", \"to_time\": \"16:30\"})",
    "        mill.insert()",
    "        mill.submit()",
    "        lathe = frappe.get_doc({\"doctype\": SPR, \"posting_date\": frappe.utils.add_days(D, -5), \"shift\": DAY, \"workstation\": LATHE, \"operator\": OP, \"company\": company})",
    "        lathe.append(\"downtime\", {\"downtime_category\": NO_LOAD, \"from_time\": \"08:00\", \"to_time\": \"16:30\"})",
    "        lathe.insert()",
    "        lathe.submit()",
    "        print(\"INFO  \" + D + \": \" + MILL + \" 4 h run, 60 min spindle breakdown (unplanned), 210 min no load (planned); \" + LATHE + \" worked 5 days earlier, nothing on \" + D)",
    "",
    "        # ---------------- 3. exception-only ----------------",
    "        doc = page()",
    "        html = doc.summary",
    "        print(\"INFO  stand-up \" + doc.name + \": \" + str(doc.exceptions) + \" thing(s) need attention, all clear = \" + str(doc.all_clear))",
    "        check(\"thing(s) need attention\" in html and doc.all_clear == 0 and doc.exceptions >= 3, \"3. the heading says how many things need attention (\" + str(doc.exceptions) + \")\")",
    "        check(\"Machines below the OEE target\" in html and MILL in html, \"3. \" + MILL + \" is listed below the 85 % OEE target\")",
    "        check(\"Unplanned stops of 30 minutes or more\" in html and SPINDLE in html and \"breakdown\" in html, \"3. the 60-minute spindle stop is listed, marked breakdown\")",
    "        check(NO_LOAD not in html, \"3. the planned 'no load' stop is not an exception, so it is not listed\")",
    "        check(\"Machines without a shift entry\" in html and LATHE in html, \"3. \" + LATHE + \" (worked 5 days earlier, no entry on the day) is listed\")",
    "        check(\"1. Shop floor yesterday\" not in html, \"3. the full machine-by-machine table is not on the exception page\")",
    "",
    "        # ---------------- 4. thresholds ----------------",
    "        settings(1, 90, 1)",
    "        html = page().summary",
    "        check(SPINDLE not in html, \"4. with Minimum Stop Minutes = 90 the 60-minute stop is left out\")",
    "        check(\"Machines below the OEE target\" not in html and \"machines at or above the OEE target.\" in html, \"4. with an OEE target of 1 % no machine is below it: one line says so\")",
    "",
    "        # ---------------- 5. the full page, and the setting ----------------",
    "        settings(0, 30, 85)",
    "        doc = page()",
    "        check(\"1. Shop floor yesterday\" in doc.summary and NO_LOAD in doc.summary and \"need attention\" not in doc.summary, \"5. Exception-Only unticked: the full page as before (every machine, every stop)\")",
    "        settings(1, 30, 85)",
    "        refused(\"5. a negative Minimum Stop Minutes is refused\", lambda: settings(1, -1, 85), \"Minimum Stop Minutes\")",
    "",
    "        print(\"\")",
    "        print(\"RESULT: \" + str(len(passed)) + \" passed, \" + str(len(failed)) + \" failed\")",
    "        print(\"Commit was left unticked, so nothing above was saved.\")",
    "        ALL_RESULTS.append([48, \"check_48_c3a_b7_standup_exceptions\", len(passed), len(failed), all_seconds(ALL_T), list(failed)])",
    "    except Exception as all_error:",
    "        all_text = frappe.utils.strip_html(str(all_error))[:400]",
    "        ALL_RESULTS.append([48, \"check_48_c3a_b7_standup_exceptions\", len(passed), len(failed) + 1, all_seconds(ALL_T), list(failed) + [\"CRASHED: \" + all_text]])",
    "    frappe.db.rollback()",
    "    all_note(\"RUNNING - Check 48 done\")",
    "",
    "# =====================================================================================================",
    "# Check 49: check_49_c3a_t1_end_to_end",
    "# =====================================================================================================",
    "if FIRST <= 49 <= LAST:",
    "    print(\"CHECK 49  (check_49_c3a_t1_end_to_end)\")",
    "    ALL_T = frappe.utils.now_datetime()",
    "    passed = []",
    "    failed = []",
    "    try:",
    "        # PEPL OS v0.49.0 - Check 49 rev 2: C3a-T1 end to end - one order through the whole Production chain:",
    "        # Sales Order (Railways, LD) -> draft Job Order -> submitted Job Order and Job Card -> the operator's shift entered",
    "        # and submitted on the kiosk -> Job Card time log, Daily OEE, Machine Week, rejected pieces in the Scrap Register ->",
    "        # Job Order panel, Estimate vs Actual Cost, LD Exposure, Skill Matrix, foreman board, Command Centre, exception-only",
    "        # stand-up -> Cycle 3a health check.",
    "        # Rev 2: the Job Card's time logs are read from the Job Card itself (a child table read on its own returned",
    "        # nothing in the System Console).",
    "        # Runs on 0.49.0 or later. System Console, Type = Python. Leave \"Commit\" UNTICKED: everything below is undone at the",
    "        # end (except the kiosk's short-lived session entry in the cache, which expires by itself).",
    "        VERSION = \"0.49.0\"",
    "        PARAMS = \"PEPL System Parameters\"",
    "        SPR = \"PEPL Shift Production Entry\"",
    "        K = \"pepl_os.pepl_production.kiosk.\"",
    "        P = \"pepl_os.pepl_production.\"",
    "        LEVEL3 = \"3 - Runs independently\"",
    "        passed = []",
    "        failed = []",
    "",
    "",
    "        def check(ok, label):",
    "            if ok:",
    "                passed.append(label)",
    "                print(\"PASS  \" + label)",
    "            else:",
    "                failed.append(label)",
    "                print(\"FAIL  \" + label)",
