    "        SCRAP = frappe.get_doc({\"doctype\": \"Item\", \"item_code\": \"CHK49-SCRAP-\" + RUN, \"item_name\": \"CHK49 Brass Turnings \" + RUN, \"item_group\": \"Brass Scrap\", \"stock_uom\": \"Kg\",",
    "                                \"is_stock_item\": 1, \"is_sales_item\": 0, \"is_purchase_item\": 0}).insert().name",
