    "        print(\"INFO  \" + MILL + \" (\" + GROUP + \", 600 / h); operator \" + OP + \" level 3; \" + SHAFT + \" 0.25 kg, BOM 1 bar x 10, 3 min on \" + MILL + \"; CST \" + cst.name + \" = \"",
